<?php require_once __DIR__.'/../includes/functions.php';require_login(['dosen']);$pdo=db();$id=(int)($_GET['krs']??0);if(isset($_GET['delete'])){$krs=(int)$_GET['delete'];$check=$pdo->prepare('SELECT k.id FROM krs k JOIN kelas kl ON kl.id=k.id_kelas WHERE k.id=? AND kl.id_dosen=?');$check->execute([$krs,lecturer_id()]);if($check->fetch())$pdo->prepare('DELETE FROM nilai WHERE id_krs=?')->execute([$krs]);flash('success','Nilai dihapus.');redirect('dosen/nilai.php');}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$krs=(int)$_POST['krs'];$scores=array_map(fn($x)=>min(100,max(0,(float)$_POST[$x])),['tugas','uts','uas']);$final=.3*$scores[0]+.3*$scores[1]+.4*$scores[2];[$letter,$weight]=grade($final);$check=$pdo->prepare('SELECT k.id FROM krs k JOIN kelas kl ON kl.id=k.id_kelas WHERE k.id=? AND kl.id_dosen=?');$check->execute([$krs,lecturer_id()]);if(!$check->fetch())exit('Akses ditolak.');$pdo->prepare('INSERT INTO nilai(id_krs,tugas,uts,uas,nilai_akhir,nilai_huruf,bobot) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE tugas=VALUES(tugas),uts=VALUES(uts),uas=VALUES(uas),nilai_akhir=VALUES(nilai_akhir),nilai_huruf=VALUES(nilai_huruf),bobot=VALUES(bobot)')->execute([$krs,...$scores,$final,$letter,$weight]);flash('success','Nilai tersimpan dan dihitung otomatis.');redirect('dosen/nilai.php');}$q=$pdo->prepare('SELECT k.id,m.npm,m.nama mahasiswa,mk.kode,mk.nama mata_kuliah,n.tugas,n.uts,n.uas,n.nilai_akhir,n.nilai_huruf FROM krs k JOIN kelas kl ON kl.id=k.id_kelas JOIN mahasiswa m ON m.id=k.id_mahasiswa JOIN mata_kuliah mk ON mk.id=k.id_mk LEFT JOIN nilai n ON n.id_krs=k.id WHERE kl.id_dosen=? ORDER BY mk.nama,m.nama');$q->execute([lecturer_id()]);$rows=$q->fetchAll();$edit=array_filter($rows,fn($r)=>$r['id']===$id);$edit=array_values($edit)[0]??null;$page_title='Input Nilai';require_once __DIR__.'/../includes/header.php';?>
<div class="d-flex justify-content-between mb-4"><h3>Input Nilai Mahasiswa</h3></div><?php if($edit):?><div class="card p-4 mb-4"><h5><?=e($edit['mahasiswa'].' — '.$edit['mata_kuliah'])?></h5><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="krs" value="<?=$edit['id']?>"><?php foreach(['tugas'=>'Tugas','uts'=>'UTS','uas'=>'UAS'] as $f=>$l):?><div class="col-md-4"><label class="form-label"><?=$l?></label><input required min="0" max="100" step=".01" type="number" class="form-control" name="<?=$f?>" value="<?=e($edit[$f]??'')?>"></div><?php endforeach?><div><button class="btn btn-primary">Simpan Nilai</button><a class="btn btn-light" href="nilai.php">Batal</a></div></form></div><?php endif?><div class="card p-4"><table class="table datatable"><thead><tr><th>Mahasiswa</th><th>Mata Kuliah</th><th>Tugas</th><th>UTS</th><th>UAS</th><th>Akhir</th><th>Huruf</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['npm'].' — '.$r['mahasiswa'])?></td><td><?=e($r['kode'].' — '.$r['mata_kuliah'])?></td><td><?=e($r['tugas']??'-')?></td><td><?=e($r['uts']??'-')?></td><td><?=e($r['uas']??'-')?></td><td><?=e($r['nilai_akhir']??'-')?></td><td><?=e($r['nilai_huruf']??'-')?></td><td class="text-nowrap"><a class="btn btn-sm btn-primary" href="?krs=<?=$r['id']?>">Input/Edit</a><?php if($r['nilai_akhir']!==null):?><a onclick="return confirm('Hapus nilai ini?')" class="btn btn-sm btn-outline-danger" href="?delete=<?=$r['id']?>">Hapus</a><?php endif?></td></tr><?php endforeach?></tbody></table></div><?php require_once __DIR__.'/../includes/footer.php';?>
